<script setup>
import { computed,onMounted,reactive,ref,watch } from 'vue';import { useRoute } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { createAdmin,deleteAdmin,listAdmin,updateAdmin } from '../../api/admin';import { options,text,formatDate } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const route=useRoute();const resource=computed(()=>route.meta.resource);const state=reactive({list:[],total:0,pageNum:1,pageSize:10,keyword:'',loading:false});const open=ref(false);const form=reactive({});const config=computed(()=>({
  'service-products':{title:'服务产品',name:'serviceName',type:'serviceType',group:'serviceType',defaults:{serviceNo:'',serviceName:'',serviceType:'PATENT_APPLICATION',targetType:'',description:'',processDesc:'',officialFee:0,agencyFee:0,estimatedCycle:'',requiredMaterials:'',advantages:'',status:1}},
  'success-cases':{title:'成功案例',name:'caseName',type:'serviceType',group:'serviceType',defaults:{caseNo:'',caseName:'',serviceType:'PATENT_APPLICATION',clientIndustry:'',technicalField:'',highlights:'',result:'',grantDate:'',description:'',publishStatus:1}},
  announcements:{title:'公告管理',name:'title',type:'announcementType',group:'announcementType',defaults:{announcementNo:'',title:'',announcementType:'BUSINESS',targetScope:'ALL',content:'',publishTime:'',startDate:'',endDate:'',isTop:0,status:1}},
}[resource.value]));const load=async()=>{state.loading=true;try{const r=await listAdmin(resource.value,{pageNum:state.pageNum,pageSize:state.pageSize,keyword:state.keyword||undefined});state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}};const edit=(row={})=>{Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,config.value.defaults,row);open.value=true};const save=async()=>{try{const payload=Object.fromEntries(Object.keys(config.value.defaults).map(key=>[key,form[key]===''?null:form[key]]));form.id?await updateAdmin(resource.value,form.id,payload):await createAdmin(resource.value,payload);ElMessage.success('内容已保存');open.value=false;load()}catch(e){ElMessage.error(messageOf(e))}};const remove=async(row)=>{await ElMessageBox.confirm('确认删除该内容？','删除确认',{type:'warning'});await deleteAdmin(resource.value,row.id);load()};watch(resource,()=>{state.pageNum=1;load()});onMounted(load)
</script>
<template><div class="page"><PageHeader :title="config.title" description="维护游客端公开展示内容"><el-button type="primary" @click="edit()">新增内容</el-button></PageHeader><div class="toolbar"><div class="filters"><el-input v-model="state.keyword" placeholder="名称或标题" clearable @keyup.enter="load"/><el-button @click="load">查询</el-button></div></div><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="id" label="ID" width="70"/><el-table-column :prop="config.name" label="名称/标题" min-width="240"/><el-table-column label="分类" width="140"><template #default="{row}">{{text(config.group,row[config.type])}}</template></el-table-column><el-table-column label="更新时间" width="160"><template #default="{row}">{{formatDate(row.updateTime||row.publishTime)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" :title="form.id?'编辑内容':'新增内容'" width="min(720px,94vw)"><el-form class="form-grid" label-position="top"><template v-if="resource==='service-products'"><el-form-item label="服务编号"><el-input v-model="form.serviceNo"/></el-form-item><el-form-item label="服务名称"><el-input v-model="form.serviceName"/></el-form-item><el-form-item label="服务类型"><el-select v-model="form.serviceType"><el-option v-for="o in options('serviceType')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="适用对象"><el-input v-model="form.targetType"/></el-form-item><el-form-item label="官方费用"><el-input-number v-model="form.officialFee" :min="0"/></el-form-item><el-form-item label="代理费用"><el-input-number v-model="form.agencyFee" :min="0"/></el-form-item><el-form-item label="预计周期"><el-input v-model="form.estimatedCycle"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item class="span-2" label="服务说明"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item class="span-2" label="服务流程"><el-input v-model="form.processDesc" type="textarea"/></el-form-item><el-form-item class="span-2" label="所需材料"><el-input v-model="form.requiredMaterials" type="textarea"/></el-form-item><el-form-item class="span-2" label="服务优势"><el-input v-model="form.advantages" type="textarea"/></el-form-item></template><template v-else-if="resource==='success-cases'"><el-form-item label="案例编号"><el-input v-model="form.caseNo"/></el-form-item><el-form-item label="案例名称"><el-input v-model="form.caseName"/></el-form-item><el-form-item label="服务类型"><el-select v-model="form.serviceType"><el-option v-for="o in options('serviceType')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="客户行业"><el-input v-model="form.clientIndustry"/></el-form-item><el-form-item label="技术领域"><el-input v-model="form.technicalField"/></el-form-item><el-form-item label="授权日期"><el-date-picker v-model="form.grantDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item class="span-2" label="案例简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item class="span-2" label="案件亮点"><el-input v-model="form.highlights" type="textarea"/></el-form-item><el-form-item class="span-2" label="处理结果"><el-input v-model="form.result" type="textarea"/></el-form-item><el-form-item label="公开状态"><el-switch v-model="form.publishStatus" :active-value="1" :inactive-value="0"/></el-form-item></template><template v-else><el-form-item label="公告编号"><el-input v-model="form.announcementNo"/></el-form-item><el-form-item label="公告标题"><el-input v-model="form.title"/></el-form-item><el-form-item label="公告类型"><el-select v-model="form.announcementType"><el-option v-for="o in options('announcementType')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="目标范围"><el-input v-model="form.targetScope"/></el-form-item><el-form-item label="发布时间"><el-date-picker v-model="form.publishTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="有效状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="form.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="form.endDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="置顶"><el-switch v-model="form.isTop" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item class="span-2" label="公告内容"><el-input v-model="form.content" type="textarea" :rows="5"/></el-form-item></template></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
